c.cpp:
class Solution {
public:
    bool reportSpam(vector<string>& message, vector<string>& bannedWords) {
        unordered_set<string> banned(bannedWords.begin(), bannedWords.end());
        int count = 0;
        for (auto& w : message)
            if (banned.count(w) && ++count >= 2) return true;
        return false;
    }
};

c.java:
class Solution {
    public boolean reportSpam(String[] message, String[] bannedWords) {
        Set<String> banned = new HashSet<>(Arrays.asList(bannedWords));
        int count = 0;
        for (String w : message) {
            if (banned.contains(w) && ++count >= 2) return true;
        }
        return false;
    }
}

